/bin/bash -lc "python - <<'PY'
import zipfile, pathlib, ast
wheel = pathlib.Path('/tmp/fsutilpkg/python_fsutil-0.17.0-py3-none-any.whl')
mods = ['archives.py','args.py','checks.py','converters.py','deps.py','info.py','io.py','operations.py','paths.py','perms.py']
with zipfile.ZipFile(wheel) as zf:
    for mod in mods:
        src = zf.read('fsutil/'+mod).decode()
        tree = ast.parse(src)
        print(f'## {mod}')
        for node in tree.body:
            if isinstance(node, ast.FunctionDef):
                args = []
                total_pos = len(node.args.args)
                defaults = [None] * (total_pos - len(node.args.defaults)) + node.args.defaults
                for arg, default in zip(node.args.args, defaults):
                    if default is None:
                        args.append(arg.arg)
                    else:
                        args.append(f\"{arg.arg}=\")
                if node.args.vararg:
                    args.append('*'+node.args.vararg.arg)
                for arg, default in zip(node.args.kwonlyargs, node.args.kw_defaults):
                    if default is None:
                        args.append(arg.arg)
                    else:
                        args.append(f\"{arg.arg}=\")
                if node.args.kwarg:
                    args.append('**'+node.args.kwarg.arg)
                print('def', node.name+'('+', '.join(args)+')')
        print()
PY"

